#!/usr/bin/env node
// Generates Kotlin/JS wrappers from the custom-elements.json manifests that ship with the
// installed @vaadin/* packages. Run after `./gradlew kotlinNpmInstall`.
//
// The manifests describe mixins separately from classes. Mixins are emitted as external
// interfaces, classes implement them, and only members declared by the class itself are repeated
// in the class body. Generated files start with MARKER; everything else in the source tree is
// preserved.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const MARKER = '// Generated by scripts/generate-wrappers.mjs. Do not edit.';
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const NODE_MODULES = path.join(ROOT, 'build', 'js', 'node_modules', '@vaadin');
const MAIN_OUT = path.join(ROOT, 'ktjs-vaadin-web-components', 'src', 'jsMain', 'kotlin', 'vaadin');
const TEST_OUT = path.join(ROOT, 'ktjs-vaadin-web-components', 'src', 'jsTest', 'kotlin', 'vaadin');

// These packages have no custom-elements.json. Their wrappers are maintained by hand.
const HAND_WRITTEN = new Set([
  '@vaadin/aura',
  '@vaadin/field-highlighter',
  '@vaadin/icons',
  '@vaadin/lit-renderer',
  '@vaadin/vaadin-lumo-styles',
  '@vaadin/vaadin-themable-mixin',
]);

const KEYWORDS = new Set(
  (
    'as break class continue do else false for fun if in interface is null object package return ' +
    'super this throw true try typealias typeof val var when while by catch constructor delegate ' +
    'dynamic field file finally get import init param property receiver set setparam where actual ' +
    'abstract annotation companion const crossinline data enum expect external final infix inline ' +
    'inner internal lateinit noinline open operator out override private protected public reified ' +
    'sealed suspend tailrec vararg it'
  ).split(' '),
);

const SIMPLE_TYPES = new Map([
  ['string', 'String'],
  ['number', 'Double'],
  ['boolean', 'Boolean'],
  ['void', 'Unit'],
  ['undefined', 'Unit'],
  ['null', 'dynamic'],
  ['never', 'Unit'],
  ['any', 'dynamic'],
  ['unknown', 'dynamic'],
  ['object', 'dynamic'],
  ['Object', 'dynamic'],
  ['Function', 'dynamic'],
  ['function', 'dynamic'],
  ['array', 'Array<dynamic>'],
  ['date', 'dynamic'],
]);

const WEB_TYPES = new Map([
  ['HTMLElement', 'web.html.HTMLElement'],
  ['HTMLInputElement', 'web.html.HTMLInputElement'],
  ['HTMLSlotElement', 'web.html.HTMLSlotElement'],
  ['HTMLTableCellElement', 'web.html.HTMLTableCellElement'],
  ['HTMLTableRowElement', 'web.html.HTMLTableRowElement'],
  ['HTMLTemplateElement', 'web.components.HTMLTemplateElement'],
  ['Element', 'web.dom.Element'],
  ['Node', 'web.dom.Node'],
  ['DocumentFragment', 'web.dom.DocumentFragment'],
  ['ShadowRoot', 'web.components.ShadowRoot'],
  ['Event', 'web.events.Event'],
  ['CustomEvent', 'web.events.Event'],
  ['EventTarget', 'web.events.EventTarget'],
  ['MouseEvent', 'web.mouse.MouseEvent'],
  ['TouchEvent', 'web.touch.TouchEvent'],
  ['KeyboardEvent', 'web.keyboard.KeyboardEvent'],
  ['FocusEvent', 'web.focus.FocusEvent'],
  ['DragEvent', 'web.dnd.DragEvent'],
  ['InputEvent', 'web.input.InputEvent'],
  ['File', 'web.file.File'],
  ['FileList', 'web.file.FileList'],
  ['Blob', 'web.blob.Blob'],
  ['Animation', 'web.animations.Animation'],
  ['DOMRect', 'web.geometry.DOMRect'],
  ['CSSStyleDeclaration', 'web.cssom.CSSStyleDeclaration'],
]);

// Mixins from @vaadin/vaadin-themable-mixin have no manifest; see the hand-written wrapper.
const EXTERNAL_MIXINS = new Map([
  ['ThemableMixin', 'vaadin.themablemixin.ThemableMixin'],
  ['ThemePropertyMixin', 'vaadin.themablemixin.ThemePropertyMixin'],
  ['ThemeDetectionMixin', 'vaadin.themablemixin.ThemeDetectionMixin'],
  ['LumoInjectionMixin', 'vaadin.themablemixin.LumoInjectionMixin'],
]);

// Members that Vaadin declares with a different type than the DOM element they extend.
// Kotlin forbids mixing two members with the same name and different types, so these are exposed
// under a `...Property` Kotlin name that maps to the original JS name via @JsName.
const DOM_TYPES = new Map([
  ['ariaLabel', 'String?'],
  ['autocapitalize', 'AutoCapitalize'],
  ['autocorrect', 'Boolean'],
  ['autofocus', 'Boolean'],
  ['draggable', 'Boolean'],
  ['hidden', 'Hidden'],
  ['inputMode', 'InputMode'],
  ['role', 'String?'],
  ['title', 'String'],
]);

const warnings = [];

function warn(message) {
  warnings.push(message);
}

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function kotlinPackage(npmName) {
  let base = npmName.replace('@vaadin/', '');
  if (base.startsWith('vaadin-')) base = base.slice('vaadin-'.length);
  return `vaadin.${base.replace(/-/g, '')}`;
}

function kotlinDir(pkg) {
  return path.join(MAIN_OUT, pkg.replace('@vaadin/', '').replace(/^vaadin-/, ''));
}

function camel(value) {
  const parts = value.split(/[-_\s]+/).filter(Boolean);
  if (parts.length === 0) return value;
  return parts
    .map((part, index) => {
      const lower = part.toLowerCase();
      if (index === 0) return lower;
      return lower.charAt(0).toUpperCase() + lower.slice(1);
    })
    .join('');
}

function pascal(value) {
  const c = camel(value);
  return c.charAt(0).toUpperCase() + c.slice(1);
}

function id(name) {
  if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(name) && !KEYWORDS.has(name)) return name;
  return `\`${name}\``;
}

function indent(text, spaces) {
  const pad = ' '.repeat(spaces);
  return text
    .split('\n')
    .map((line) => (line.length > 0 ? pad + line : line))
    .join('\n');
}

function kdoc(description, spaces = 0) {
  if (!description) return '';
  const clean = description
    .replace(/\r\n/g, '\n')
    .trim()
    .replace(/\*\//g, '*&#47;')
    .replace(/\/\*/g, '/&#42;');
  const body = clean
    .split('\n')
    .map((line) => ` * ${line}`.trimEnd())
    .join('\n');
  return indent(`/**\n${body}\n */\n`, spaces);
}

function splitTop(text, separator) {
  const parts = [];
  let current = '';
  let depth = 0;
  let quote = null;
  for (const char of text) {
    if (quote) {
      current += char;
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      current += char;
      continue;
    }
    if ('<({['.includes(char)) depth += 1;
    if ('>)}]'.includes(char)) depth -= 1;
    if (char === separator && depth === 0) {
      parts.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  parts.push(current);
  return parts;
}

function stripMarkers(text) {
  let value = text.trim().replace(/=$/, '').trim();
  let nullable = false;
  while (value.startsWith('!') || value.startsWith('?')) {
    if (value.startsWith('?')) nullable = true;
    value = value.slice(1).trim();
  }
  return { value, nullable };
}

function mapType(text, pkg) {
  if (!text) return 'dynamic';
  const { value, nullable: markerNullable } = stripMarkers(text);
  if (!value) return 'dynamic';

  const union = splitTop(value, '|').map((part) => part.trim()).filter(Boolean);
  const nonNull = union.filter((part) => part !== 'null' && part !== 'undefined');
  const nullable = markerNullable || nonNull.length !== union.length;
  if (nonNull.length === 0) return 'dynamic';

  const mapped = [...new Set(nonNull.map((part) => mapSingle(part, pkg)))];
  let base;
  if (mapped.length === 1) {
    base = mapped[0];
  } else if (mapped.every((type) => type === 'String')) {
    base = 'String';
  } else if (mapped.every((type) => type === 'Double' || type === 'Int')) {
    base = 'Double';
  } else {
    base = 'dynamic';
  }

  if (nullable && base !== 'dynamic' && base !== 'Unit') return `${base}?`;
  return base;
}

function mapSingle(text, pkg) {
  const { value: raw } = stripMarkers(text);
  const value = raw.trim();
  if (!value) return 'dynamic';

  if (value.endsWith('[]')) {
    return `Array<${mapType(value.slice(0, -2), pkg)}>`;
  }

  const array = /^(?:Readonly)?Array\s*<(.+)>$/.exec(value);
  if (array) return `Array<${mapType(array[1], pkg)}>`;

  const promise = /^Promise\s*<(.+)>$/.exec(value);
  if (promise) return `kotlin.js.Promise<${mapType(promise[1], pkg)}>`;

  const arrow = /^\((.*)\)\s*=>\s*(.+)$/.exec(value);
  if (arrow) return functionType(arrow[1], arrow[2], pkg);

  const singleArrow = /^([A-Za-z_$][\w$]*)\s*=>\s*(.+)$/.exec(value);
  if (singleArrow) return `(dynamic) -> ${mapType(singleArrow[2], pkg)}`;

  const closureFunction = /^function\s*\((.*)\)\s*:\s*(.+)$/.exec(value);
  if (closureFunction) return functionType(closureFunction[1], closureFunction[2], pkg);

  if (value.startsWith('{')) return 'dynamic';
  if (value.includes('&')) {
    const parts = splitTop(value, '&').map((part) => part.trim());
    if (parts.some((part) => /HTMLElement$/.test(part))) return 'web.html.HTMLElement';
    return 'dynamic';
  }

  if (SIMPLE_TYPES.has(value)) return SIMPLE_TYPES.get(value);
  if (WEB_TYPES.has(value)) return WEB_TYPES.get(value);
  if (value === 'Date') return 'kotlin.js.Date';
  if (/^'.*'$/.test(value) || /^".*"$/.test(value)) return 'String';

  const declaration = findDeclaration(value, pkg);
  if (declaration) return declaration.kotlinFqn;
  return 'dynamic';
}

function functionType(parameters, returns, pkg) {
  const params = parameters.trim()
    ? splitTop(parameters, ',')
        .map((parameter) => {
          const text = parameter.trim();
          if (!text) return null;
          if (text.startsWith('...')) return `vararg ${mapType(text.slice(3), pkg)}`;
          const colon = text.lastIndexOf(':');
          const type = colon >= 0 ? text.slice(colon + 1) : text;
          const mapped = mapType(type, pkg);
          return mapped === 'Unit' ? 'dynamic' : mapped;
        })
        .filter(Boolean)
        .join(', ')
    : '';
  const mappedReturn = mapType(returns, pkg);
  return `(${params}) -> ${mappedReturn}`;
}


function resolveReference(reference, pkg, modulePath) {
  if (!reference) return null;
  if (reference.package) {
    if (!reference.package.startsWith('@vaadin/')) return null;
    const pieces = reference.package.split('/');
    const targetPackage = `${pieces[0]}/${pieces[1]}`;
    const targetModule = pieces.slice(2).join('/');
    return `${targetPackage}|${targetModule}|${reference.name}`;
  }
  if (reference.module) {
    // Manifest `module` references are relative to the package root, not to the declaring module.
    return `${pkg}|${reference.module}|${reference.name}`;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------
// Manifest registry

const packages = fs
  .readdirSync(NODE_MODULES, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .map((entry) => {
    const dir = path.join(NODE_MODULES, entry.name);
    const manifest = path.join(dir, 'custom-elements.json');
    if (!fs.existsSync(manifest)) return null;
    return { dir, name: readJson(path.join(dir, 'package.json')).name, manifest: readJson(manifest) };
  })
  .filter(Boolean)
  .filter((entry) => !HAND_WRITTEN.has(entry.name))
  .sort((a, b) => a.name.localeCompare(b.name));

const registry = new Map();
const declarations = [];

for (const entry of packages) {
  const pkg = entry.name;
  for (const module of entry.manifest.modules) {
    for (const declaration of module.declarations || []) {
      const record = {
        ...declaration,
        pkg,
        module: module.path,
        kotlinPackage: kotlinPackage(pkg),
        isExported:
          declaration.kind === 'mixin' ||
          declaration.kind === 'class' ||
          (module.exports || []).some(
            (exported) =>
              exported.kind === 'js' && exported.declaration && exported.declaration.name === declaration.name,
          ),
      };
      record.kotlinName =
        declaration.kind === 'class' && declaration.tagName
          ? `${declaration.name}Element`
          : declaration.name;
      record.kotlinFqn = `${record.kotlinPackage}.${record.kotlinName}`;
      record.facadeName =
        declaration.kind === 'class'
          ? declaration.tagName
            ? declaration.name
            : `${declaration.name}Statics`
          : null;
      const key = `${pkg}|${module.path}|${declaration.name}`;
      registry.set(key, record);
      declarations.push(record);
    }
  }
}

// Functions used as mixins are emitted as interfaces instead of functions.
const mixinFunctions = new Set();
for (const declaration of declarations) {
  for (const mixin of declaration.mixins || []) {
    const key = resolveReference(mixin, declaration.pkg, declaration.module);
    const target = key && registry.get(key);
    if (target && target.kind === 'function' && target.name.endsWith('Mixin')) {
      mixinFunctions.add(target);
      target.kind = 'mixin';
    }
  }
}

const declarationsByName = new Map();
for (const declaration of declarations) {
  if (declaration.kind !== 'class' && declaration.kind !== 'mixin') continue;
  const list = declarationsByName.get(declaration.name) || [];
  list.push(declaration);
  declarationsByName.set(declaration.name, list);
}

function findDeclaration(name, preferredPackage) {
  const candidates = declarationsByName.get(name);
  if (!candidates || candidates.length === 0) return null;
  const samePackage = candidates.find((candidate) => candidate.pkg === preferredPackage);
  if (samePackage) return samePackage;
  return candidates.length === 1 ? candidates[0] : null;
}

function resolveMixin(reference, declaration) {
  const key = resolveReference(reference, declaration.pkg, declaration.module);
  if (!key) return null;
  const target = registry.get(key);
  if (target) {
    if (target.kind === 'mixin') return { fqn: target.kotlinFqn, declaration: target };
    return null;
  }
  if (EXTERNAL_MIXINS.has(reference.name)) {
    return { fqn: EXTERNAL_MIXINS.get(reference.name), declaration: null };
  }
  warn(`unresolved mixin ${reference.name} referenced from ${declaration.pkg}/${declaration.name}`);
  return null;
}

function directMixins(declaration) {
  const result = [];
  const seen = new Set();
  for (const mixin of declaration.mixins || []) {
    if (mixin.name === 'dedupeMixin') continue;
    const resolved = resolveMixin(mixin, declaration);
    if (!resolved || seen.has(resolved.fqn)) continue;
    seen.add(resolved.fqn);
    result.push(resolved);
  }
  return result;
}

function mixinClosure(declaration, visited = new Set()) {
  const result = [];
  for (const mixin of directMixins(declaration)) {
    if (visited.has(mixin.fqn)) continue;
    visited.add(mixin.fqn);
    result.push(mixin);
    if (mixin.declaration) result.push(...mixinClosure(mixin.declaration, visited));
  }
  return result;
}

function superclassOf(declaration) {
  const superclass = declaration.superclass;
  if (!superclass) return null;
  const key = resolveReference(superclass, declaration.pkg, declaration.module);
  const target = key && registry.get(key);
  if (target && target.kind === 'class') return target;
  if (superclass.name === 'EventTarget') return 'web.events.EventTarget';
  if (declaration.tagName) return 'web.html.HTMLElement';
  return null;
}

function superclassClosure(declaration) {
  const result = [];
  let current = declaration;
  const seen = new Set();
  while (current) {
    const parent = superclassOf(current);
    if (!parent || typeof parent === 'string') break;
    if (seen.has(parent.kotlinFqn)) break;
    seen.add(parent.kotlinFqn);
    result.push(parent);
    current = parent;
  }
  return result;
}

function allMixins(declaration) {
  const result = [...mixinClosure(declaration)];
  for (const parent of superclassClosure(declaration)) result.push(...mixinClosure(parent));
  const seen = new Set();
  return result.filter((mixin) => {
    if (seen.has(mixin.fqn)) return false;
    seen.add(mixin.fqn);
    return true;
  });
}

// Kotlin names that members inherited from the DOM superclass, generated superclasses, and mixins
// already occupy, together with their types. Used to add `override` and to rename members whose
// JS name collides with an incompatible inherited member.
function inheritedMembers(declaration) {
  const result = new Map();
  const visit = (current) => {
    for (const member of ownMembers(current)) {
      const type = memberType(member, current.pkg);
      const disposition = memberDisposition(member.name, type);
      if (disposition === 'skip') continue;
      const name =
        disposition === 'rename'
          ? resolveName(`${member.name}Property`, type)
          : resolveName(member.name, type);
      if (!result.has(name)) result.set(name, type);
    }
  };
  for (const parent of superclassClosure(declaration)) visit(parent);
  for (const mixin of allMixins(declaration)) {
    if (mixin.declaration) visit(mixin.declaration);
  }
  return result;
}

function directSuperTypes(declaration) {
  const result = [];
  const parent = superclassOf(declaration);
  if (parent && typeof parent !== 'string') result.push(parent);
  for (const mixin of directMixins(declaration)) result.push(mixin.declaration);
  return result.filter(Boolean);
}

function removeRedundantMixins(mixins) {
  const fqns = new Set(mixins.map((mixin) => mixin.fqn));
  return mixins.filter((mixin) => {
    if (!mixin.declaration) return true;
    const parents = allMixins(mixin.declaration).map((parent) => parent.fqn);
    return !parents.some((parent) => fqns.has(parent));
  });
}

function ownMembers(declaration) {
  return (declaration.members || []).filter(
    (member) => !member.inheritedFrom && (!member.privacy || member.privacy === 'public'),
  );
}

function memberType(member, pkg) {
  if (member.kind === 'field') return mapType(member.type && member.type.text, pkg);
  return mapType(member.return && member.return.type && member.return.type.text, pkg);
}

function resolveName(name, type, inherited) {
  let kotlin = name;
  while (inherited !== undefined && inherited.has(name) && inherited.get(name) !== type) {
    kotlin = `${kotlin}Property`;
  }
  return kotlin;
}

// A member that the DOM element already provides with the same type is omitted from the wrapper:
// it stays available through `web.html.HTMLElement`. A DOM member with a different type cannot be
// redeclared (Kotlin forbids the clash, and DOM members are final), so the wrapper member is
// exposed under a `...Property` name that maps to the original JS name.
function memberDisposition(name, type) {
  const domType = DOM_TYPES.get(name);
  if (domType === undefined) return 'keep';
  return domType === type ? 'skip' : 'rename';
}

function renderParameters(parameters, pkg, external = true, optionalDefault = 'definedExternally') {
  return (parameters || [])
    .map((parameter) => {
      const name = id(parameter.name || 'arg');
      const text = (parameter.type && parameter.type.text) || '';
      if (text.trim().startsWith('...')) {
        return `vararg ${name}: ${mapType(text.trim().slice(3), pkg).replace(/\?$/, '')}`;
      }
      let type = mapType(text, pkg);
      if (type === 'Unit') type = 'dynamic';
      const optional =
        parameter.optional ||
        parameter.default !== undefined ||
        /^\s*optional\b/i.test(parameter.description || '');
      if (!optional) return `${name}: ${type}`;
      return `${name}: ${type} = ${external ? 'definedExternally' : optionalDefault}`;
    })
    .join(', ');
}

function renderMember(member, pkg, spaces, inherited) {
  const type = memberType(member, pkg);
  const disposition = memberDisposition(member.name, type);
  if (disposition === 'skip') return null;
  const renamed = disposition === 'rename';
  const name = renamed ? resolveName(`${member.name}Property`, type, inherited) : resolveName(member.name, type, inherited);
  const description = renamed
    ? `${member.description ? `${member.description.trim()}\n\n` : ''}Maps to the \`${member.name}\` property. Renamed in Kotlin because the DOM member with the same name has a different type.`
    : member.description;
  const doc = kdoc(description, spaces);
  const pad = ' '.repeat(spaces);
  const annotation = renamed ? `${pad}@JsName("${member.name}")\n` : '';
  const override = inherited && inherited.get(name) === type ? `${pad}override ` : pad;
  if (member.kind === 'field') {
    const keyword = member.readonly ? 'val' : 'var';
    return `${doc}${annotation}${override}${keyword} ${id(name)}: ${type}`;
  }
  const parameters = renderParameters(member.parameters, pkg);
  return `${doc}${annotation}${override}fun ${id(name)}(${parameters})${type === 'Unit' ? '' : `: ${type}`}`;
}

function renderMembers(declaration, spaces, inherited) {
  return ownMembers(declaration)
    .map((member) => renderMember(member, declaration.pkg, spaces, inherited))
    .filter(Boolean)
    .join('\n');
}

function collectStatics(declaration, packageName) {
  const result = new Map();
  for (const member of declaration.members || []) {
    if (member.static && !member.inheritedFrom && (!member.privacy || member.privacy === 'public')) {
      const signature = `${member.kind}|${member.name}|${(member.parameters || []).map((p) => mapType(p.type && p.type.text, packageName)).join(',')}`;
      if (!result.has(signature)) result.set(signature, member);
    }
  }
  for (const mixin of allMixins(declaration)) {
    if (!mixin.declaration) continue;
    for (const member of mixin.declaration.members || []) {
      if (!member.static || member.inheritedFrom || (member.privacy && member.privacy !== 'public')) continue;
      const signature = `${member.kind}|${member.name}|${(member.parameters || []).map((p) => mapType(p.type && p.type.text, packageName)).join(',')}`;
      if (!result.has(signature)) result.set(signature, member);
    }
  }
  return [...result.values()];
}

function renderStaticMember(member, pkg, spaces) {
  const doc = kdoc(member.description, spaces);
  const pad = ' '.repeat(spaces);
  if (member.kind === 'field') return `${doc}${pad}val ${id(member.name)}: ${memberType(member, pkg)}`;
  const parameters = renderParameters(member.parameters, pkg);
  const returns = memberType(member, pkg);
  return `${doc}${pad}fun ${id(member.name)}(${parameters})${returns === 'Unit' ? '' : `: ${returns}`}`;
}

function collectEvents(declaration) {
  const result = new Map();
  const visit = (current) => {
    for (const event of current.events || []) {
      if (!result.has(event.name)) result.set(event.name, event);
    }
    for (const mixin of directMixins(current)) {
      if (mixin.declaration) visit(mixin.declaration);
    }
    for (const parent of superclassClosure(current)) visit(parent);
  };
  visit(declaration);
  return [...result.values()];
}

function collectAttributes(declaration) {
  const result = new Map();
  for (const attribute of declaration.attributes || []) {
    if (!result.has(attribute.name)) result.set(attribute.name, attribute);
  }
  return [...result.values()];
}

function uniqueNames(items, baseName) {
  const used = new Set();
  return items.map((item) => {
    let name = baseName(item);
    if (!used.has(name)) {
      used.add(name);
      return { ...item, kotlinProperty: name };
    }
    let index = 2;
    while (used.has(`${name}${index}`)) index += 1;
    const unique = `${name}${index}`;
    used.add(unique);
    return { ...item, kotlinProperty: unique };
  });
}

// ---------------------------------------------------------------------------------------------
// File emission

const written = new Set();

function writeFile(file, content) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${MARKER}\n${content.trimEnd()}\n`);
  written.add(path.resolve(file));
}

function header(pkg, imports = []) {
  return [`package ${kotlinPackage(pkg)}`, ...imports.map((value) => `import ${value}`), ''].join('\n');
}

function emitMixin(declaration) {
  const parents = removeRedundantMixins(directMixins(declaration)).map((mixin) => mixin.fqn);
  const body = renderMembers(declaration, 4);
  const doc = kdoc(declaration.description);
  const extendsClause = parents.length > 0 ? ` : ${[...new Set(parents)].join(', ')}` : '';
  const content = `${header(declaration.pkg)}\n${doc}external interface ${declaration.kotlinName}${extendsClause} {\n${body}\n}`;
  writeFile(path.join(kotlinDir(declaration.pkg), `${declaration.kotlinName}.kt`), content);
}

function emitClass(declaration) {
  const superType = superclassOf(declaration);
  const base = typeof superType === 'string' ? superType : superType ? superType.kotlinFqn : null;
  const mixins = removeRedundantMixins(directMixins(declaration));
  const superTypes = [...(base ? [base] : []), ...mixins.map((mixin) => mixin.fqn)];
  const inherited = inheritedMembers(declaration);
  const body = renderMembers(declaration, 4, inherited);
  const doc = kdoc(declaration.description);
  const extendsClause = superTypes.length > 0 ? ` : ${[...new Set(superTypes)].join(', ')}` : '';
  const lines = [header(declaration.pkg), doc, `abstract external class ${declaration.kotlinName}${extendsClause} {`, body, '}'];

  const moduleName = `${declaration.kotlinName}Module`;
  const statics = collectStatics(declaration, declaration.pkg);
  const isElement = Boolean(declaration.tagName);

  if (statics.length > 0) {
    const staticInterface = `${declaration.kotlinName}StaticMembers`;
    lines.push(
      '',
      `private external interface ${staticInterface} {`,
      statics.map((member) => renderStaticMember(member, declaration.pkg, 4)).join('\n'),
      '}',
    );
    lines.push(
      '',
      `@JsModule("${declaration.pkg}/${declaration.module}")`,
      `private external object ${moduleName} {`,
      `    val ${id(declaration.name)}: ${staticInterface}`,
      '}',
      '',
      `object ${declaration.facadeName} {`,
      statics
        .map((member) => {
          const call = `${moduleName}.${id(declaration.name)}.${id(member.name)}`;
          if (member.kind === 'field') {
            return `${kdoc(member.description, 4)}    val ${id(member.name)}: ${memberType(member, declaration.pkg)}\n        get() = ${call}`;
          }
          const parameters = renderParameters(member.parameters, declaration.pkg, false, 'js("undefined")');
          const returns = memberType(member, declaration.pkg);
          const args = (member.parameters || []).map((parameter) => id(parameter.name || 'arg')).join(', ');
          const prefix = returns === 'Unit' ? '' : 'return ';
          return `${kdoc(member.description, 4)}    fun ${id(member.name)}(${parameters})${returns === 'Unit' ? '' : `: ${returns}`} {\n        ${prefix}${call}(${args})\n    }`;
        })
        .join('\n\n'),
      '}',
    );
  } else if (!isElement) {
    lines.push(
      '',
      `@JsModule("${declaration.pkg}/${declaration.module}")`,
      `private external object ${moduleName} {`,
      `    val ${id(declaration.name)}: dynamic`,
      '}',
      '',
      `/** The class registered by \`${declaration.pkg}/${declaration.module}\`. */`,
      `fun ${camel(declaration.name)}Class(): dynamic = ${moduleName}.${id(declaration.name)}`,
    );
  }

  if (isElement) {
    const tagProperty = camel(declaration.tagName.replace(/^vaadin-/, ''));
    const baseName = declaration.name;
    lines.push(
      '',
      `/** The \`<${declaration.tagName}>\` custom element. */`,
      `object ${declaration.facadeName}TagName {`,
      `    inline val ${id(tagProperty)}: web.dom.TagName<${declaration.kotlinName}>`,
      `        get() = web.dom.TagName("${declaration.tagName}")`,
      '}',
    );
    if (statics.length === 0) {
      lines.push(
        '',
        `@JsModule("${declaration.pkg}/${declaration.module}")`,
        `private external object ${moduleName} {`,
        `    val ${id(declaration.name)}: dynamic`,
        '}',
      );
    }
    lines.push(
      '',
      `/** Imports \`${declaration.pkg}/${declaration.module}\`, registering \`<${declaration.tagName}>\`, and returns the element class. */`,
      `fun register${baseName}(): dynamic = ${moduleName}.${id(declaration.name)}`,
      '',
      `/** Creates a \`<${declaration.tagName}>\` element. The custom element is registered on first use. */`,
      `fun create${baseName}(configure: ${declaration.kotlinName}.() -> Unit = {}): ${declaration.kotlinName} {`,
      `    register${baseName}()`,
      `    return web.dom.document.createElement(${declaration.facadeName}TagName.${id(tagProperty)}).apply(configure)`,
      '}',
    );

    const attributes = uniqueNames(collectAttributes(declaration), (attribute) => camel(attribute.name));
    if (attributes.length > 0) {
      lines.push(
        '',
        `/** Attribute names of \`<${declaration.tagName}>\`, for use with \`setAttribute\`. */`,
        `object ${declaration.facadeName}Attributes {`,
        attributes
          .map(
            (attribute) =>
              `${kdoc(attribute.description, 4)}    const val ${id(attribute.kotlinProperty)}: String = "${attribute.name}"`,
          )
          .join('\n'),
        '}',
      );
    }

    const events = uniqueNames(collectEvents(declaration), (event) => camel(event.name));
    if (events.length > 0) {
      lines.push(
        '',
        `/** Typed event names of \`<${declaration.tagName}>\`, for use with \`addEventHandler\`. */`,
        `object ${declaration.facadeName}Events {`,
        events
          .map(
            (event) =>
              `${kdoc(event.description, 4)}    val ${id(event.kotlinProperty)}: web.events.EventType<web.events.Event>\n        get() = web.events.EventType("${event.name}")`,
          )
          .join('\n\n'),
        '}',
      );
    }
  }

  writeFile(path.join(kotlinDir(declaration.pkg), `${declaration.kotlinName}.kt`), lines.join('\n'));
}

function moduleFileBase(modulePath) {
  const name = path.posix.basename(modulePath, '.js').replace(/^vaadin-/, '');
  return pascal(name);
}

function emitModuleDeclarations(pkg, modulePath, items) {
  const kotlinPkg = kotlinPackage(pkg);
  const base = moduleFileBase(modulePath);
  const directory = kotlinDir(pkg);
  const exportsLines = [`@file:JsModule("${pkg}/${modulePath}")`, '', `package ${kotlinPkg}`, ''];

  const functions = items.filter((item) => item.kind === 'function' && !mixinFunctions.has(item));
  const variables = items.filter((item) => item.kind === 'variable');

  for (const declaration of functions) {
    const returns = mapType(declaration.return && declaration.return.type && declaration.return.type.text, declaration.pkg);
    exportsLines.push(
      kdoc(declaration.description),
      `external fun ${id(declaration.name)}(${renderParameters(declaration.parameters, declaration.pkg)})${returns === 'Unit' ? '' : `: ${returns}`}`,
      '',
    );
  }

  const moduleName = `${base}ExportsModule`;
  if (variables.length > 0) {
    exportsLines.push(`internal external object ${moduleName} {`);
    for (const variable of variables) exportsLines.push(`    val ${id(variable.name)}: dynamic`);
    exportsLines.push('}', '');
  }

  if (exportsLines.length > 4) {
    writeFile(path.join(directory, `${base}Exports.kt`), exportsLines.join('\n'));
  }

  if (variables.length > 0) {
    const valueLines = [
      `package ${kotlinPkg}`,
      '',
      `/** The values exported by \`${pkg}/${modulePath}\`. */`,
      `object ${base}Exports {`,
      ...variables.map(
        (variable) =>
          `${kdoc(variable.description, 4)}    val ${id(variable.name)}: ${mapType(variable.type && variable.type.text, pkg)}\n        get() = ${moduleName}.${id(variable.name)}`,
      ),
      '}',
      '',
    ];
    writeFile(path.join(directory, `${base}Values.kt`), valueLines.join('\n'));
  }
}

for (const declaration of declarations) {
  if (!declaration.isExported) continue;
  if (declaration.kind === 'mixin') emitMixin(declaration);
  else if (declaration.kind === 'class') emitClass(declaration);
}

const moduleGroups = new Map();
for (const declaration of declarations) {
  if (declaration.kind !== 'function' && declaration.kind !== 'variable') continue;
  if (!declaration.isExported) continue;
  if (declaration.kind === 'function' && mixinFunctions.has(declaration)) continue;
  const key = `${declaration.pkg}|${declaration.module}`;
  const group = moduleGroups.get(key) || [];
  group.push(declaration);
  moduleGroups.set(key, group);
}
for (const group of moduleGroups.values()) {
  emitModuleDeclarations(group[0].pkg, group[0].module, group);
}

// ---------------------------------------------------------------------------------------------
// Cleanup of stale generated files

function walk(directory) {
  if (!fs.existsSync(directory)) return;
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const full = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      walk(full);
      if (fs.readdirSync(full).length === 0) fs.rmdirSync(full);
    } else if (entry.name.endsWith('.kt')) {
      const absolute = path.resolve(full);
      if (written.has(absolute)) continue;
      const content = fs.readFileSync(full, 'utf8');
      if (content.startsWith(MARKER)) fs.unlinkSync(full);
    }
  }
}

walk(MAIN_OUT);
walk(TEST_OUT);

for (const warning of warnings) console.warn(`warning: ${warning}`);
console.log(`generated ${written.size} files`);
